from pagination import paginate, page_count


def test_req_first_page_starts_at_first_item():
    assert paginate(list(range(50)), 1) == list(range(20))


def test_req_second_page_with_custom_size():
    assert paginate(list(range(50)), 2, per_page=10) == list(range(10, 20))


def test_reg_page_size_respected():
    assert len(paginate(list(range(100)), 3, per_page=5)) == 5


def test_reg_page_count_exact():
    assert page_count(100, per_page=10) == 10
